// Original procedural score: 108 BPM, minor pentatonic lead, bass and drums.
export class ArenaMusic{
 constructor(Context=globalThis.AudioContext||globalThis.webkitAudioContext){this.Context=Context;this.ctx=null;this.master=null;this.volume=.35;this.enabled=true;this.playing=false;this.timer=null;this.step=0;this.next=0;this.nodes=new Set();this.generation=0;}
 async play(){const generation=this.generation;if(!this.enabled||this.playing)return;if(!this.Context)throw Error('Audio non supportato');if(!this.ctx){this.ctx=new this.Context();this.master=this.ctx.createGain();this.master.gain.value=this.volume*.55;this.master.connect(this.ctx.destination);this.noise=this.ctx.createBuffer(1,this.ctx.sampleRate*.25,this.ctx.sampleRate);const data=this.noise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1}await this.ctx.resume();if(generation!==this.generation||!this.enabled||this.playing)return;this.playing=true;this.next=this.ctx.currentTime+.04;this.step=0;this.schedule();this.timer=setInterval(()=>this.schedule(),40);}
 setVolume(v){this.volume=Math.max(0,Math.min(1,Number(v)||0));if(this.ctx)this.master.gain.setTargetAtTime(this.volume*.55,this.ctx.currentTime,.035)}
 keep(node){this.nodes.add(node);node.onended=()=>{this.nodes.delete(node);node.disconnect()};return node}
 note(midi,t,duration,gain,type='triangle',cutoff=1800){const osc=this.keep(this.ctx.createOscillator()),amp=this.ctx.createGain(),filter=this.ctx.createBiquadFilter();osc.type=type;osc.frequency.value=440*Math.pow(2,(midi-69)/12);filter.type='lowpass';filter.frequency.value=cutoff;amp.gain.setValueAtTime(.0001,t);amp.gain.exponentialRampToValueAtTime(gain,t+.015);amp.gain.exponentialRampToValueAtTime(.0001,t+duration);osc.connect(filter);filter.connect(amp);amp.connect(this.master);osc.start(t);osc.stop(t+duration+.02);osc.onended=()=>{this.nodes.delete(osc);osc.disconnect();amp.disconnect();filter.disconnect()}}
 kick(t){const osc=this.keep(this.ctx.createOscillator()),amp=this.ctx.createGain();osc.frequency.setValueAtTime(125,t);osc.frequency.exponentialRampToValueAtTime(38,t+.14);amp.gain.setValueAtTime(.42,t);amp.gain.exponentialRampToValueAtTime(.0001,t+.23);osc.connect(amp);amp.connect(this.master);osc.start(t);osc.stop(t+.25);osc.onended=()=>{this.nodes.delete(osc);osc.disconnect();amp.disconnect()}}
 drum(t,snare=false){const src=this.keep(this.ctx.createBufferSource()),filter=this.ctx.createBiquadFilter(),amp=this.ctx.createGain();src.buffer=this.noise;filter.type=snare?'bandpass':'highpass';filter.frequency.value=snare?1800:8000;const duration=snare?.13:.045;amp.gain.setValueAtTime(snare?.16:.045,t);amp.gain.exponentialRampToValueAtTime(.0001,t+duration);src.connect(filter);filter.connect(amp);amp.connect(this.master);src.start(t);src.stop(t+duration+.01);src.onended=()=>{this.nodes.delete(src);src.disconnect();filter.disconnect();amp.disconnect()}}
 schedule(){if(!this.playing)return;const tick=60/108/4;let guard=0;if(this.next<this.ctx.currentTime-.3)this.next=this.ctx.currentTime+.02;while(this.next<this.ctx.currentTime+.18&&guard++<32){const n=this.step%256,bar=Math.floor(n/16),beat=n%16,t=this.next,root=[35,31,38,33][Math.floor(bar/2)%4];if(beat===0||beat===8||beat===11)this.kick(t);if(beat===4||beat===12)this.drum(t,true);if(beat%2===0)this.drum(t);if([0,3,6,8,11,14].includes(beat))this.note(root+(beat===14?12:0),t,tick*1.5,.18,'sawtooth',420);if(beat===0){this.note(root+24,t,tick*13,.032,'triangle',900);this.note(root+31,t,tick*13,.024,'triangle',1100)}if(bar>=4&&beat%2===0){const pattern=[0,7,10,14,12,7,3,10],offset=pattern[(beat/2+bar)%8];this.note(root+36+offset,t,tick*1.5,.045,'triangle',2400)}this.next+=tick;this.step++;}}
 pause(){this.generation++;this.playing=false;if(this.timer!==null)clearInterval(this.timer);this.timer=null;for(const node of this.nodes){try{node.stop()}catch{}}this.nodes.clear();}
 disable(){this.enabled=false;this.pause()}
}
